import * as console from "std/console"
export function test(): null {
  console.log("jvm-std-console-log");
  console.error("jvm-std-console-error");
}

import * as math from "std/math"
export function test(): int {
  let a: int = math.absInt(-7);
  let b: int = math.absInt(7);
  let c: int = math.minInt(3, 9);
  let d: int = math.maxInt(3, 9);
  let e: int = math.minInt(-5, 2);
  let f: int = math.maxInt(-5, 2);
  let g: int = math.absInt(-9007199254740991);
  let small: int = a + b + c + d + e + f;
  let diff: int = g - 9007199254740968;
  return small + diff;
}

import * as time from "std/time"
export function test(): int {
  let t: int = time.nowMillis();
  let granularity: int = t % 1000;
  if (t > 1700000000000 && granularity === 0) {
    return 1;
  }
  return 0;
}

import * as str from "std/string"
import * as math from "std/math"
import * as console from "std/console"
export function test(): null {
  let n: int = str.length("abc");
  let x: int = math.absInt(n - 10);
  let trimmed: string = str.trim("  deal  ");
  console.log(trimmed);
  if (str.contains(trimmed, "eal") && x === 7) {
    console.log("compose-ok");
  }
}
